public class UniformCrossoverTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("mask(10, seed 5)", "ABBABABABB", UniformCrossover.mask(10, 5L));
            check("mask(8, seed 2024)", "AABAAABA", UniformCrossover.mask(8, 2024L));
            check("cross of two marker parents follows the mask", "aBBaBaBaBB",
                    UniformCrossover.cross("aaaaaaaaaa", "BBBBBBBBBB", 5L));
            check("cross(\"abcdefgh\", \"12345678\", seed 2024)", "ab3def7h",
                    UniformCrossover.cross("abcdefgh", "12345678", 2024L));
            check("two identical parents give that same child", "hello",
                    UniformCrossover.cross("hello", "hello", 99L));
            check("empty parents give an empty child", "", UniformCrossover.cross("", "", 1L));
            check("the same seed repeats the crossover",
                    UniformCrossover.cross("abcdefgh", "12345678", 77L),
                    UniformCrossover.cross("abcdefgh", "12345678", 77L));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        String thrown = "no exception";
        try {
            UniformCrossover.cross("abc", "abcd", 1L);
        } catch (IllegalArgumentException e) {
            thrown = "IllegalArgumentException";
        } catch (RuntimeException e) {
            thrown = e.getClass().getSimpleName();
        }
        check("parents of different lengths are rejected", "IllegalArgumentException", thrown);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

