/**
 * Uniform crossover: a seeded coin flip chooses a parent at every position.
 */
public class UniformCrossover {

    public static String mask(int length, long seed) {
        java.util.Random rng = new java.util.Random(seed);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < length; i++) {
            sb.append(rng.nextBoolean() ? 'A' : 'B');
        }
        return sb.toString();
    }

    public static String cross(String a, String b, long seed) {
        if (a.length() != b.length()) {
            throw new IllegalArgumentException("parents must be the same length");
        }
        java.util.Random rng = new java.util.Random(seed);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < a.length(); i++) {
            sb.append(rng.nextBoolean() ? a.charAt(i) : b.charAt(i));
        }
        return sb.toString();
    }
}
